import React, { createContext, createElement, forwardRef } from "react";

const MotionContext = createContext({});

const createDefinition = (propNames) => ({
  isEnabled: (props) => propNames.some((name) => !!props[name]),
});

const featureDefinitions = {
  measureLayout: createDefinition(["layout", "layoutId", "drag"]),
  animation: createDefinition([
    "animate",
    "exit",
    "variants",
    "whileHover",
    "whileTap",
    "whileFocus",
    "whileDrag",
    "whileInView",
  ]),
  exit: createDefinition(["exit"]),
  drag: createDefinition(["drag", "dragControls"]),
  focus: createDefinition(["whileFocus"]),
  hover: createDefinition(["whileHover", "onHoverStart", "onHoverEnd"]),
  tap: createDefinition(["whileTap", "onTap", "onTapStart", "onTapCancel"]),
  pan: createDefinition(["onPan", "onPanStart", "onPanSessionStart", "onPanEnd"]),
  inView: createDefinition(["whileInView", "onViewportEnter", "onViewportLeave"]),
};

const featureNames = Object.keys(featureDefinitions);

const makeRenderlessComponent = (hook) => (props) => {
  hook(props);
  return null;
};

const domAnimation = {
  animation: makeRenderlessComponent(() => {}),
  exit: makeRenderlessComponent(() => {}),
  hover: makeRenderlessComponent(() => {}),
  tap: makeRenderlessComponent(() => {}),
  focus: makeRenderlessComponent(() => {}),
  inView: makeRenderlessComponent(() => {}),
};

function loadFeatures(features) {
  for (const key in features) featureDefinitions[key].Component = features[key];
}

const isValidMotionProp = (key) =>
  key === "animate" || key === "initial" || key === "transition" || key.startsWith("while");

const filterProps = (props) => {
  const filtered = {};
  for (const key of Object.keys(props)) {
    if (!isValidMotionProp(key)) filtered[key] = props[key];
  }
  return filtered;
};

class VisualElementHandler extends React.Component {
  render() {
    return this.props.children;
  }
}

function createMotionComponent({ preloadedFeatures, Component }) {
  preloadedFeatures && loadFeatures(preloadedFeatures);
  function MotionComponent(props, externalRef) {
    const features = [];
    for (const name of featureNames) {
      const { isEnabled, Component: Feature } = featureDefinitions[name];
      if (isEnabled(props) && Feature) features.push(createElement(Feature, { key: name, ...props }));
    }
    return createElement(
      VisualElementHandler,
      { props },
      features,
      createElement(
        MotionContext.Provider,
        { value: {} },
        createElement(Component, { ...filterProps(props), ref: externalRef }),
      ),
    );
  }
  return forwardRef(MotionComponent);
}

export const motion = new Proxy(createMotionComponent, {
  get: (_target, key) => createMotionComponent({ preloadedFeatures: domAnimation, Component: key }),
});
